INSERT INTO public.tb_pipelines VALUES (68, 'Teste 1 - Pipeline Básica', 'Trigger manual, set variable, log, end', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger Manual", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger Manual</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Definir Nome", "variable_name": "nome_app", "variable_value": "DMC DataLoad"}, "html": "<div class=\"node-content\"><span>Definir Nome</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "log_node", "label": "Log Início", "level": "info", "message": "Pipeline iniciada: {{nome_app}}"}, "html": "<div class=\"node-content\"><span>Log Início</span></div>", "name": "log_node", "class": "log_node", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 12:58:31.621584-03', '2026-03-23 12:58:39.875514-03');
INSERT INTO public.tb_pipelines VALUES (81, 'Teste 2 - HTTP + Condição', 'Chama API JSONPlaceholder, verifica resposta com condição', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"url": "https://jsonplaceholder.typicode.com/todos/1", "body": "", "type": "http_request", "label": "Buscar Todos", "method": "GET", "headers": "{}", "timeout": 15, "auth_type": "none", "output_variable": "todo_data"}, "html": "<div class=\"node-content\"><span>Buscar Todos</span></div>", "name": "http_request", "class": "http_request", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "set_variable", "label": "Extrair Status", "variable_name": "completed", "variable_value": "{{todo_data}}"}, "html": "<div class=\"node-content\"><span>Extrair Status</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "condition", "label": "Todo Concluído?", "operator": "not_empty", "left_operand": "{{completed}}", "right_operand": ""}, "html": "<div class=\"node-content\"><span>Todo Concluído?</span></div>", "name": "condition", "class": "condition", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}, "output_2": {"connections": [{"node": "6", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log TRUE", "level": "info", "message": "API retornou dados válidos: {{todo_data}}"}, "html": "<div class=\"node-content\"><span>Log TRUE</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "log_node", "label": "Log FALSE", "level": "warning", "message": "Sem dados da API"}, "html": "<div class=\"node-content\"><span>Log FALSE</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}, {"node": "6", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:52.9115-03', '2026-03-23 13:05:52.9115-03');
INSERT INTO public.tb_pipelines VALUES (82, 'Teste 3 - HTTP + Transform + Loop', 'Busca usuários da API, limita 3, faz loop', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"url": "https://jsonplaceholder.typicode.com/users", "body": "", "type": "http_request", "label": "Buscar Usuários", "method": "GET", "headers": "{}", "timeout": 15, "auth_type": "none", "output_variable": "users"}, "html": "<div class=\"node-content\"><span>Buscar Usuários</span></div>", "name": "http_request", "class": "http_request", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "transform", "label": "Filtrar por Cidade", "limit_count": "3", "limit_offset": "0", "input_variable": "users", "transform_type": "limit", "output_variable": "top_users"}, "html": "<div class=\"node-content\"><span>Filtrar por Cidade</span></div>", "name": "transform", "class": "transform", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "loop", "label": "Loop Usuários", "input_variable": "top_users", "max_iterations": 10, "output_variable": "loop_result", "iterator_variable": "user"}, "html": "<div class=\"node-content\"><span>Loop Usuários</span></div>", "name": "loop", "class": "loop", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log Resultado", "level": "info", "message": "Processados {{loop_result}} registros de {{users}} usuários"}, "html": "<div class=\"node-content\"><span>Log Resultado</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:53.469994-03', '2026-03-23 13:05:53.469994-03');
INSERT INTO public.tb_pipelines VALUES (83, 'Teste 4 - Script + Variáveis', 'Calcula preço x quantidade, verifica se > 1000', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Def. Preço", "variable_name": "preco", "variable_value": "150.50"}, "html": "<div class=\"node-content\"><span>Def. Preço</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "set_variable", "label": "Def. Qtd", "variable_name": "quantidade", "variable_value": "10"}, "html": "<div class=\"node-content\"><span>Def. Qtd</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "script", "label": "Calcular Total", "script_code": "$preco * $quantidade", "output_variable": "total", "script_language": "expression"}, "html": "<div class=\"node-content\"><span>Calcular Total</span></div>", "name": "script", "class": "script", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "condition", "label": "Total > 1000?", "operator": ">", "left_operand": "{{total}}", "right_operand": "1000"}, "html": "<div class=\"node-content\"><span>Total > 1000?</span></div>", "name": "condition", "class": "condition", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}, "output_2": {"connections": [{"node": "7", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "log_node", "label": "Pedido Grande", "level": "warning", "message": "Pedido grande! Total={{total}}"}, "html": "<div class=\"node-content\"><span>Pedido Grande</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1100, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "log_node", "label": "Pedido Normal", "level": "info", "message": "Pedido normal. Total={{total}}"}, "html": "<div class=\"node-content\"><span>Pedido Normal</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1100, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}}}, "8": {"id": 8, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "6", "input": "output_1"}, {"node": "7", "input": "output_1"}]}}, "outputs": []}}}}}', '', '{"preco": 0, "quantidade": 0}', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:53.924591-03', '2026-03-23 13:05:53.924591-03');
INSERT INTO public.tb_pipelines VALUES (84, 'Teste 5 - HTTP POST', 'Envia dados para API REST e verifica resposta', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Dados Post", "variable_name": "post_body", "variable_value": "{\"title\":\"Pipeline Test\",\"body\":\"Teste DMC DataLoad\",\"userId\":1}"}, "html": "<div class=\"node-content\"><span>Dados Post</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"url": "https://jsonplaceholder.typicode.com/posts", "body": "{{post_body}}", "type": "http_request", "label": "POST JSONPlaceholder", "method": "POST", "headers": "{\"Content-Type\": \"application/json\"}", "timeout": 15, "auth_type": "none", "output_variable": "post_result"}, "html": "<div class=\"node-content\"><span>POST JSONPlaceholder</span></div>", "name": "http_request", "class": "http_request", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "condition", "label": "Post criado?", "operator": "not_empty", "left_operand": "{{post_result}}", "right_operand": ""}, "html": "<div class=\"node-content\"><span>Post criado?</span></div>", "name": "condition", "class": "condition", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}, "output_2": {"connections": [{"node": "6", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log Sucesso", "level": "info", "message": "Post criado com sucesso! Res: {{post_result}}"}, "html": "<div class=\"node-content\"><span>Log Sucesso</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "log_node", "label": "Log Falha", "level": "error", "message": "Falha ao criar post"}, "html": "<div class=\"node-content\"><span>Log Falha</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}, {"node": "6", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:53.939265-03', '2026-03-23 13:05:53.939265-03');
INSERT INTO public.tb_pipelines VALUES (85, 'Teste 6 - Delay + Logs', 'Delay de 2s entre logs', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "log_node", "label": "Log Início", "level": "info", "message": "Iniciando com delay..."}, "html": "<div class=\"node-content\"><span>Log Início</span></div>", "name": "log_node", "class": "log_node", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "delay", "label": "Aguardar 2s", "delay_seconds": 2}, "html": "<div class=\"node-content\"><span>Aguardar 2s</span></div>", "name": "delay", "class": "delay", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "set_variable", "label": "Timestamp", "variable_name": "ts", "variable_value": "executado"}, "html": "<div class=\"node-content\"><span>Timestamp</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log Fim", "level": "info", "message": "Delay concluído! Status={{ts}}"}, "html": "<div class=\"node-content\"><span>Log Fim</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:55.013737-03', '2026-03-23 13:05:55.013737-03');
INSERT INTO public.tb_pipelines VALUES (86, 'Teste 7 - Pipeline Grande', '11 nós: HTTP→Transform×2→Script→Condition→Loop→Log→End', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger Grande", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger Grande</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Def. API URL", "variable_name": "api_url", "variable_value": "https://jsonplaceholder.typicode.com/posts"}, "html": "<div class=\"node-content\"><span>Def. API URL</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"url": "{{api_url}}", "body": "", "type": "http_request", "label": "GET Posts", "method": "GET", "headers": "{}", "timeout": 20, "auth_type": "none", "output_variable": "posts"}, "html": "<div class=\"node-content\"><span>GET Posts</span></div>", "name": "http_request", "class": "http_request", "pos_x": 500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "transform", "label": "Limitar 5", "limit_count": "5", "limit_offset": "0", "input_variable": "posts", "transform_type": "limit", "output_variable": "top_posts"}, "html": "<div class=\"node-content\"><span>Limitar 5</span></div>", "name": "transform", "class": "transform", "pos_x": 700, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "transform", "label": "Contar", "agg_field": "id", "agg_operation": "count", "input_variable": "top_posts", "transform_type": "aggregate", "output_variable": "count_result"}, "html": "<div class=\"node-content\"><span>Contar</span></div>", "name": "transform", "class": "transform", "pos_x": 900, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "script", "label": "Extrair Contagem", "script_code": "is_array($count_result) ? ($count_result[\"value\"] ?? 0) : $count_result", "output_variable": "total_count", "script_language": "expression"}, "html": "<div class=\"node-content\"><span>Extrair Contagem</span></div>", "name": "script", "class": "script", "pos_x": 1100, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "condition", "label": "Posts >= 5?", "operator": ">=", "left_operand": "{{total_count}}", "right_operand": "5"}, "html": "<div class=\"node-content\"><span>Posts >= 5?</span></div>", "name": "condition", "class": "condition", "pos_x": 1300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "6", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}, "output_2": {"connections": [{"node": "9", "output": "input_1"}]}}}, "8": {"id": 8, "data": {"type": "loop", "label": "Processar Posts", "input_variable": "top_posts", "max_iterations": 10, "output_variable": "processed", "iterator_variable": "post"}, "html": "<div class=\"node-content\"><span>Processar Posts</span></div>", "name": "loop", "class": "loop", "pos_x": 1500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "10", "output": "input_1"}]}}}, "9": {"id": 9, "data": {"type": "log_node", "label": "Log Poucos Posts", "level": "warning", "message": "Poucos posts: {{total_count}}"}, "html": "<div class=\"node-content\"><span>Log Poucos Posts</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1500, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "10", "output": "input_1"}]}}}, "10": {"id": 10, "data": {"type": "log_node", "label": "Log Final", "level": "info", "message": "Pipeline grande finalizada! {{total_count}} posts processados"}, "html": "<div class=\"node-content\"><span>Log Final</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "8", "input": "output_1"}, {"node": "9", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "11", "output": "input_1"}]}}}, "11": {"id": 11, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "10", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:57.062273-03', '2026-03-23 13:05:57.062273-03');
INSERT INTO public.tb_pipelines VALUES (97, 'Teste 6 - Delay + Logs', 'Delay de 2s entre logs', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "log_node", "label": "Log Início", "level": "info", "message": "Iniciando com delay..."}, "html": "<div class=\"node-content\"><span>Log Início</span></div>", "name": "log_node", "class": "log_node", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "delay", "label": "Aguardar 2s", "delay_seconds": 2}, "html": "<div class=\"node-content\"><span>Aguardar 2s</span></div>", "name": "delay", "class": "delay", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "set_variable", "label": "Timestamp", "variable_name": "ts", "variable_value": "executado"}, "html": "<div class=\"node-content\"><span>Timestamp</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log Fim", "level": "info", "message": "Delay concluído! Status={{ts}}"}, "html": "<div class=\"node-content\"><span>Log Fim</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:09:08.209497-03', '2026-03-23 13:09:08.209497-03');
INSERT INTO public.tb_pipelines VALUES (87, 'Teste 8 - Múltiplas APIs', '2 chamadas HTTP paralelas + comparação', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}, {"node": "3", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"url": "https://jsonplaceholder.typicode.com/posts/1", "body": "", "type": "http_request", "label": "GET Post 1", "method": "GET", "headers": "{}", "timeout": 15, "auth_type": "none", "output_variable": "post1"}, "html": "<div class=\"node-content\"><span>GET Post 1</span></div>", "name": "http_request", "class": "http_request", "pos_x": 300, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"url": "https://jsonplaceholder.typicode.com/posts/1/comments", "body": "", "type": "http_request", "label": "GET Comments", "method": "GET", "headers": "{}", "timeout": 15, "auth_type": "none", "output_variable": "comments"}, "html": "<div class=\"node-content\"><span>GET Comments</span></div>", "name": "http_request", "class": "http_request", "pos_x": 300, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "script", "label": "Contar Comments", "script_code": "is_array($comments) ? count($comments) : 0", "output_variable": "num_comments", "script_language": "expression"}, "html": "<div class=\"node-content\"><span>Contar Comments</span></div>", "name": "script", "class": "script", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}, {"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "condition", "label": "Mais de 3 comments?", "operator": ">", "left_operand": "{{num_comments}}", "right_operand": "3"}, "html": "<div class=\"node-content\"><span>Mais de 3 comments?</span></div>", "name": "condition", "class": "condition", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}, "output_2": {"connections": [{"node": "7", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "log_node", "label": "Muitos Comentários", "level": "info", "message": "Post tem {{num_comments}} comentários!"}, "html": "<div class=\"node-content\"><span>Muitos Comentários</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "log_node", "label": "Poucos Comentários", "level": "warning", "message": "Post tem apenas {{num_comments}} comentários"}, "html": "<div class=\"node-content\"><span>Poucos Comentários</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}}}, "8": {"id": 8, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "6", "input": "output_1"}, {"node": "7", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:57.661825-03', '2026-03-23 13:05:57.661825-03');
INSERT INTO public.tb_pipelines VALUES (88, 'Teste 9 - Transforms Avançados', 'Filter→Limit→Aggregate(count)→Aggregate(max)', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"url": "https://jsonplaceholder.typicode.com/todos", "body": "", "type": "http_request", "label": "GET Todos", "method": "GET", "headers": "{}", "timeout": 15, "auth_type": "none", "output_variable": "all_todos"}, "html": "<div class=\"node-content\"><span>GET Todos</span></div>", "name": "http_request", "class": "http_request", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "transform", "label": "Filtrar Completos", "filter_field": "completed", "filter_value": "1", "input_variable": "all_todos", "transform_type": "filter", "filter_operator": "equals", "output_variable": "completed_todos"}, "html": "<div class=\"node-content\"><span>Filtrar Completos</span></div>", "name": "transform", "class": "transform", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "transform", "label": "Limitar 10", "limit_count": "10", "limit_offset": "0", "input_variable": "completed_todos", "transform_type": "limit", "output_variable": "limited_todos"}, "html": "<div class=\"node-content\"><span>Limitar 10</span></div>", "name": "transform", "class": "transform", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "transform", "label": "Agregar Count", "agg_field": "id", "agg_operation": "count", "input_variable": "limited_todos", "transform_type": "aggregate", "output_variable": "agg_count"}, "html": "<div class=\"node-content\"><span>Agregar Count</span></div>", "name": "transform", "class": "transform", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "transform", "label": "Agregar Max ID", "agg_field": "id", "agg_operation": "max", "input_variable": "limited_todos", "transform_type": "aggregate", "output_variable": "agg_max"}, "html": "<div class=\"node-content\"><span>Agregar Max ID</span></div>", "name": "transform", "class": "transform", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "log_node", "label": "Log Resultado", "level": "info", "message": "Filtrados: {{agg_count}}, Max ID: {{agg_max}}"}, "html": "<div class=\"node-content\"><span>Log Resultado</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "6", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}}}, "8": {"id": 8, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:58.732231-03', '2026-03-23 13:05:58.732231-03');
INSERT INTO public.tb_pipelines VALUES (89, 'Teste 10 - Pipeline CRON', 'Agendada para minuto 7 (CRON: 7 * * * *)', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger CRON", "trigger_type": "cron", "cron_expression": "7 * * * *"}, "html": "<div class=\"node-content\"><span>Trigger CRON</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Timestamp", "variable_name": "exec_time", "variable_value": "2026-03-23 17:05:59"}, "html": "<div class=\"node-content\"><span>Timestamp</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "log_node", "label": "Log CRON", "level": "info", "message": "Pipeline CRON executada em {{exec_time}}"}, "html": "<div class=\"node-content\"><span>Log CRON</span></div>", "name": "log_node", "class": "log_node", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', '7 * * * *', 'cron', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:59.240012-03', '2026-03-23 13:05:59.240012-03');
INSERT INTO public.tb_pipelines VALUES (90, 'Teste 1 - Pipeline Básica (cópia)', 'Trigger manual, set variable, log, end', 'nocode', false, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger Manual", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger Manual</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Definir Nome", "variable_name": "nome_app", "variable_value": "DMC DataLoad"}, "html": "<div class=\"node-content\"><span>Definir Nome</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "log_node", "label": "Log Início", "level": "info", "message": "Pipeline iniciada: {{nome_app}}"}, "html": "<div class=\"node-content\"><span>Log Início</span></div>", "name": "log_node", "class": "log_node", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:05:59.250924-03', '2026-03-23 13:05:59.250924-03');
INSERT INTO public.tb_pipelines VALUES (91, 'Teste 7 - Pipeline Grande (importado)', '11 nós: HTTP→Transform×2→Script→Condition→Loop→Log→End', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger Grande", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger Grande</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Def. API URL", "variable_name": "api_url", "variable_value": "https://jsonplaceholder.typicode.com/posts"}, "html": "<div class=\"node-content\"><span>Def. API URL</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"url": "{{api_url}}", "body": "", "type": "http_request", "label": "GET Posts", "method": "GET", "headers": "{}", "timeout": 20, "auth_type": "none", "output_variable": "posts"}, "html": "<div class=\"node-content\"><span>GET Posts</span></div>", "name": "http_request", "class": "http_request", "pos_x": 500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "transform", "label": "Limitar 5", "limit_count": "5", "limit_offset": "0", "input_variable": "posts", "transform_type": "limit", "output_variable": "top_posts"}, "html": "<div class=\"node-content\"><span>Limitar 5</span></div>", "name": "transform", "class": "transform", "pos_x": 700, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "transform", "label": "Contar", "agg_field": "id", "agg_operation": "count", "input_variable": "top_posts", "transform_type": "aggregate", "output_variable": "count_result"}, "html": "<div class=\"node-content\"><span>Contar</span></div>", "name": "transform", "class": "transform", "pos_x": 900, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "script", "label": "Extrair Contagem", "script_code": "is_array($count_result) ? ($count_result[\"value\"] ?? 0) : $count_result", "output_variable": "total_count", "script_language": "expression"}, "html": "<div class=\"node-content\"><span>Extrair Contagem</span></div>", "name": "script", "class": "script", "pos_x": 1100, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "condition", "label": "Posts >= 5?", "operator": ">=", "left_operand": "{{total_count}}", "right_operand": "5"}, "html": "<div class=\"node-content\"><span>Posts >= 5?</span></div>", "name": "condition", "class": "condition", "pos_x": 1300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "6", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}, "output_2": {"connections": [{"node": "9", "output": "input_1"}]}}}, "8": {"id": 8, "data": {"type": "loop", "label": "Processar Posts", "input_variable": "top_posts", "max_iterations": 10, "output_variable": "processed", "iterator_variable": "post"}, "html": "<div class=\"node-content\"><span>Processar Posts</span></div>", "name": "loop", "class": "loop", "pos_x": 1500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "10", "output": "input_1"}]}}}, "9": {"id": 9, "data": {"type": "log_node", "label": "Log Poucos Posts", "level": "warning", "message": "Poucos posts: {{total_count}}"}, "html": "<div class=\"node-content\"><span>Log Poucos Posts</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1500, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "10", "output": "input_1"}]}}}, "10": {"id": 10, "data": {"type": "log_node", "label": "Log Final", "level": "info", "message": "Pipeline grande finalizada! {{total_count}} posts processados"}, "html": "<div class=\"node-content\"><span>Log Final</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "8", "input": "output_1"}, {"node": "9", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "11", "output": "input_1"}]}}}, "11": {"id": 11, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "10", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '[]', 1, '["teste"]', 1, '2026-03-23 13:05:59.252534-03', '2026-03-23 13:05:59.252534-03');
INSERT INTO public.tb_pipelines VALUES (96, 'Teste 5 - HTTP POST', 'Envia dados para API REST e verifica resposta', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Dados Post", "variable_name": "post_body", "variable_value": "{\"title\":\"Pipeline Test\",\"body\":\"Teste DMC DataLoad\",\"userId\":1}"}, "html": "<div class=\"node-content\"><span>Dados Post</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"url": "https://jsonplaceholder.typicode.com/posts", "body": "{{post_body}}", "type": "http_request", "label": "POST JSONPlaceholder", "method": "POST", "headers": "{\"Content-Type\": \"application/json\"}", "timeout": 15, "auth_type": "none", "output_variable": "post_result"}, "html": "<div class=\"node-content\"><span>POST JSONPlaceholder</span></div>", "name": "http_request", "class": "http_request", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "condition", "label": "Post criado?", "operator": "not_empty", "left_operand": "{{post_result}}", "right_operand": ""}, "html": "<div class=\"node-content\"><span>Post criado?</span></div>", "name": "condition", "class": "condition", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}, "output_2": {"connections": [{"node": "6", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log Sucesso", "level": "info", "message": "Post criado com sucesso! Res: {{post_result}}"}, "html": "<div class=\"node-content\"><span>Log Sucesso</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "log_node", "label": "Log Falha", "level": "error", "message": "Falha ao criar post"}, "html": "<div class=\"node-content\"><span>Log Falha</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}, {"node": "6", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:09:07.089687-03', '2026-03-23 13:09:07.089687-03');
