lass": "log_node", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:09:11.835577-03', '2026-03-23 13:09:11.835577-03');
INSERT INTO public.tb_pipelines VALUES (255, 'Test Desktop Export', '', 'nocode', false, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger"}, "html": "", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 200, "inputs": {}, "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}, "typenode": false}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Set_variable", "variable_name": "relatorio", "variable_value": "[{\"departamento\":\"TI\",\"funcionarios\":15,\"orcamento\":250000},{\"departamento\":\"RH\",\"funcionarios\":8,\"orcamento\":120000},{\"departamento\":\"Vendas\",\"funcionarios\":22,\"orcamento\":380000},{\"departamento\":\"Marketing\",\"funcionarios\":10,\"orcamento\":180000},{\"departamento\":\"Financeiro\",\"funcionarios\":6,\"orcamento\":95000}]"}, "html": "", "name": "set_variable", "class": "set_variable", "pos_x": 400, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}, "typenode": false}, "3": {"id": 3, "data": {"type": "file_export", "label": "Export Desktop CSV", "filename": "DMC_Relatorio_Departamentos_{date}", "export_format": "csv", "input_variable": "{{relatorio}}", "output_variable": "export_csv", "export_directory": "desktop"}, "html": "", "name": "file_export", "class": "file_export", "pos_x": 700, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}, "typenode": false}, "4": {"id": 4, "data": {"type": "file_export", "label": "Export Desktop JSON", "filename": "DMC_Relatorio_Departamentos_{date}", "export_format": "json", "input_variable": "{{relatorio}}", "output_variable": "export_json", "export_directory": "desktop"}, "html": "", "name": "file_export", "class": "file_export", "pos_x": 1000, "pos_y": 200, "inputs": {"inpu