INSERT INTO public.tb_pipelines VALUES (169, 'Teste 13 - Regex', 'Extração e teste com regex', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "SetTexto", "variable_name": "texto", "variable_value": "CPF: 123.456.789-00 e 987.654.321-11"}, "html": "<div class=\"node-content\"><span>SetTexto</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}, {"node": "4", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "regex", "label": "ExtrairCPF", "pattern": "/\\d{3}\\.\\d{3}\\.\\d{3}-\\d{2}/", "regex_mode": "match_all", "input_variable": "texto", "output_variable": "cpfs"}, "html": "<div class=\"node-content\"><span>ExtrairCPF</span></div>", "name": "regex", "class": "regex", "pos_x": 500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "regex", "label": "TestCPF", "pattern": "/\\d{3}\\.\\d{3}\\.\\d{3}-\\d{2}/", "regex_mode": "test", "input_variable": "texto", "output_variable": "tem_cpf"}, "html": "<div class=\"node-content\"><span>TestCPF</span></div>", "name": "regex", "class": "regex", "pos_x": 500, "pos_y": 250, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log", "log_message": "CPFs encontrados"}, "html": "<div class=\"node-content\"><span>Log</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}, {"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:35:41.24907-03', '2026-03-23 13:35:41.24907-03');
INSERT INTO public.tb_pipelines VALUES (170, 'Teste 14 - CSV Parse', 'Parse de CSV em array', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "SetCSV", "variable_name": "csv_data", "variable_value": "nome,idade,cidade\nJoão,30,São Paulo\nMaria,25,Rio\nPedro,40,Curitiba"}, "html": "<div class=\"node-content\"><span>SetCSV</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "csv_parse", "label": "ParseCSV", "delimiter": ",", "enclosure": "\"", "has_header": "true", "input_variable": "csv_data", "output_variable": "pessoas"}, "html": "<div class=\"node-content\"><span>ParseCSV</span></div>", "name": "csv_parse", "class": "csv_parse", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "log_node", "label": "Log", "log_message": "Pessoas parseadas"}, "html": "<div class=\"node-content\"><span>Log</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:35:41.25134-03', '2026-03-23 13:35:41.25134-03');
INSERT INTO public.tb_pipelines VALUES (171, 'Teste 15 - Counter', 'Contador incremental', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "counter", "label": "SetInicial", "counter_name": "total", "counter_value": "10", "counter_action": "set", "output_variable": "total"}, "html": "<div class=\"node-content\"><span>SetInicial</span></div>", "name": "counter", "class": "counter", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "counter", "label": "Incrementar1", "counter_name": "total", "counter_action": "increment", "output_variable": "total"}, "html": "<div class=\"node-content\"><span>Incrementar1</span></div>", "name": "counter", "class": "counter", "pos_x": 500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "counter", "label": "Incrementar2", "counter_name": "total", "counter_action": "increment", "output_variable": "total"}, "html": "<div class=\"node-content\"><span>Incrementar2</span></div>", "name": "counter", "class": "counter", "pos_x": 500, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log", "log_message": "Total: {{total}}"}, "html": "<div class=\"node-content\"><span>Log</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:35:41.253361-03', '2026-03-23 13:35:41.253361-03');
INSERT INTO public.tb_pipelines VALUES (232, 'Teste 10 - Pipeline CRON', 'Agendada para minuto 47 (CRON: 47 * * * *)', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger CRON", "trigger_type": "cron", "cron_expression": "47 * * * *"}, "html": "<div class=\"node-content\"><span>Trigger CRON</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Timestamp", "variable_name": "exec_time", "variable_value": "2026-03-23 17:45:12"}, "html": "<div class=\"node-content\"><span>Timestamp</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "log_node", "label": "Log CRON", "level": "info", "message": "Pipeline CRON executada em {{exec_time}}"}, "html": "<div class=\"node-content\"><span>Log CRON</span></div>", "name": "log_node", "class": "log_node", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', '47 * * * *', 'cron', '{}', 1, '["teste"]', 1, '2026-03-23 13:45:12.52178-03', '2026-03-23 13:45:12.52178-03');
