INSERT INTO public.tb_pipelines VALUES (194, 'Teste 6 - Delay + Logs', 'Delay de 2s entre logs', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "log_node", "label": "Log Início", "level": "info", "message": "Iniciando com delay..."}, "html": "<div class=\"node-content\"><span>Log Início</span></div>", "name": "log_node", "class": "log_node", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "delay", "label": "Aguardar 2s", "delay_seconds": 2}, "html": "<div class=\"node-content\"><span>Aguardar 2s</span></div>", "name": "delay", "class": "delay", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "set_variable", "label": "Timestamp", "variable_name": "ts", "variable_value": "executado"}, "html": "<div class=\"node-content\"><span>Timestamp</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log Fim", "level": "info", "message": "Delay concluído! Status={{ts}}"}, "html": "<div class=\"node-content\"><span>Log Fim</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": 