INSERT INTO public.tb_pipelines VALUES (201, 'Teste 11 - Switch/Case', 'Roteamento multi-branch', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "SetStatus", "variable_name": "status", "variable_value": "ativo"}, "html": "<div class=\"node-content\"><span>SetStatus</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "switch_case", "label": "Switch", "case_1": "ativo", "case_2": "inativo", "switch_variable": "status"}, "html": "<div class=\"node-content\"><span>Switch</span></div>", "name": "switch_case", "class": "switch_case", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}, "output_2": {"connections": [{"node": "5", "output": "input_1"}]}, "output_3": {"connections": [{"node": "6", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "log_node", "label": "Log Ativo", "log_message": "Status é ATIVO"}, "html": "<div class=\"node-content\"><span>Log Ativo</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log Inativo", "log_message": "Status é INATIVO"}, "html": "<div class=\"node-content\"><