INSERT INTO public.tb_pipelines VALUES (204, 'Teste 14 - CSV Parse', 'Parse de CSV em array', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "SetCSV", "variable_name": "csv_data", "variable_value": "nome,idade,cidade\nJoão,30,São Paulo\nMaria,25,Rio\nPedro,40,Curitiba"}, "html": "<div class=\"node-content\"><span>SetCSV</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "csv_parse", "label": "ParseCSV", "delimiter": ",", "enclosure": "\"", "has_header": "true", "input_variable": "csv_data", "output_variable": "pessoas"}, "html": "<div class=\"node-content\"><span>ParseCSV</span></div>", "name": "csv_parse", "class": "csv_parse", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "log_node", "label": "Log", "log_message": "Pessoas parseadas"}, "html": "<div class=\"node-content\"><span>Log</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:44:49.759849-03', '2026-03-23 13:44:49.759849-03');
INSERT INTO public.tb_pipelines VALUES (205, 'Teste 15 - Counter', 'Contador incremental', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "counter", "label": "SetInicial", "counter_name": "total", "counter_value": "10", "counter_action": "set", "output_variable": "total"}, "html": "<div class=\"node-content\"><span>SetInicial</span></div>", "name": "counter", "class": "counter", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "counter", "label": "Incrementar1", "counter_name": "total", "counter_action": "increment", "output_variable": "total"}, "html": "<div class=\"node-content\"><span>Incrementar1</span></div>", "name": "counter", "class": "counter", "pos_x": 500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "counter", "label": "Incrementar2", "counter_name": "total", "counter_action": "increment", "output_variable": "total"}, "html": "<div class=\"node-content\"><span>Incrementar2</span></div>", "name": "counter", "class": "counter", "pos_x": 500, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log", "log_message": "Total: {{total}}"}, "html": "<div class=\"node-content\"><span>Log</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:44:49.76496-03', '2026-03-23 13:44:49.76496-03');
INSERT INTO public.tb_pipelines VALUES (236, 'Teste 12 - Format Template', 'Formatação de texto com template', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}, {"node": "3", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "SetNome", "variable_name": "nome", "variable_value": "João"}, "html": "<div class=\"node-content\"><span>SetNome</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "set_variable", "label": "SetPedido", "variable_name": "pedido", "variable_value": "12345"}, "html": "<div class=\"node-content\"><span>SetPedido</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "format_template", "label": "Formatar", "template": "Olá {{nome}}, seu pedido #{{pedido}} foi confirmado.", "output_variable": "mensagem"}, "html": "<div class=\"node-content\"><span>Formatar</span></div>", "name": "format_template", "class": "format_template", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}, {"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "LogMsg", "log_message": "{{mensagem}}"}, "html": "<div class=\"node-content\"><span>LogMsg</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 13:45:12.550739-03', '2026-03-23 13:45:12.550739-03');
