INSERT INTO public.tb_pipelines VALUES (293, 'Teste 7 - Pipeline Grande', '11 nós: HTTP→Transform×2→Script→Condition→Loop→Log→End', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger Grande", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger Grande</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Def. API URL", "variable_name": "api_url", "variable_value": "https://jsonplaceholder.typicode.com/posts"}, "html": "<div class=\"node-content\"><span>Def. API URL</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"url": "{{api_url}}", "body": "", "type": "http_request", "label": "GET Posts", "method": "GET", "headers": "{}", "timeout": 20, "auth_type": "none", "output_variable": "posts"}, "html": "<div class=\"node-content\"><span>GET Posts</span></div>", "name": "http_request", "class": "http_request", "pos_x": 500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "transform", "label": "Limitar 5", "limit_count": "5", "limit_offset": "0", "input_variable": "posts", "transform_type": "limit", "output_variable": "top_posts"}, "html": "<div class=\"node-content\"><span>Limitar 5</span></div>", "name": "transform", "class": "transform", "pos_x": 700, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "transform", "label": "Contar", "agg_field": "id", "agg_operation": "count", "input_variable": "top_posts", "transform_type": "aggregate", "output_variable": "count_result"}, "html": "<div class=\"node-content\"><span>Contar</span></div>", "name": "transform", "class": "transform", "pos_x": 900, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "script", "label": "Extrair Contagem", "script_code": "is_array($count_result) ? ($count_result[\"value\"] ?? 0) : $count_result", "output_variable": "total_count", "script_language": "expression"}, "html": "<div class=\"node-content\"><span>Extrair Contagem</span></div>", "name": "script", "class": "script", "pos_x": 1100, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "condition", "label": "Posts >= 5?", "operator": ">=", "left_operand": "{{total_count}}", "right_operand": "5"}, "html": "<div class=\"node-content\"><span>Posts >= 5?</span></div>", "name": "condition", "class": "condition", "pos_x": 1300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "6", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}, "output_2": {"connections": [{"node": "9", "output": "input_1"}]}}}, "8": {"id": 8, "data": {"type": "loop", "label": "Processar Posts", "input_variable": "top_posts", "max_iterations": 10, "output_variable": "processed", "iterator_variable": "post"}, "html": "<div class=\"node-content\"><span>Processar Posts</span></div>", "name": "loop", "class": "loop", "pos_x": 1500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "10", "output": "input_1"}]}}}, "9": {"id": 9, "data": {"type": "log_node", "label": "Log Poucos Posts", "level": "warning", "message": "Poucos posts: {{total_count}}"}, "html": "<div class=\"node-content\"><span>Log Poucos Posts</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1500, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "10", "output": "input_1"}]}}}, "10": {"id": 10, "data": {"type": "log_node", "label": "Log Final", "level": "info", "message": "Pipeline grande finalizada! {{total_count}} posts processados"}, "html": "<div class=\"node-content\"><span>Log Final</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "8", "input": "output_1"}, {"node": "9", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "11", "output": "input_1"}]}}}, "11": {"id": 11, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "10", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 14:13:22.078969-03', '2026-03-23 14:13:22.078969-03');
INSERT INTO public.tb_pipelines VALUES (294, 'Teste 8 - Múltiplas APIs', '2 chamadas HTTP paralelas + comparação', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}, {"node": "3", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"url": "https://jsonplaceholder.typicode.com/posts/1", "body": "", "type": "http_request", "label": "GET Post 1", "method": "GET", "headers": "{}", "timeout": 15, "auth_type": "none", "output_variable": "post1"}, "html": "<div class=\"node-content\"><span>GET Post 1</span></div>", "name": "http_request", "class": "http_request", "pos_x": 300, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"url": "https://jsonplaceholder.typicode.com/posts/1/comments", "body": "", "type": "http_request", "label": "GET Comments", "method": "GET", "headers": "{}", "timeout": 15, "auth_type": "none", "output_variable": "comments"}, "html": "<div class=\"node-content\"><span>GET Comments</span></div>", "name": "http_request", "class": "http_request", "pos_x": 300, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "script", "label": "Contar Comments", "script_code": "is_array($comments) ? count($comments) : 0", "output_variable": "num_comments", "script_language": "expression"}, "html": "<div class=\"node-content\"><span>Contar Comments</span></div>", "name": "script", "class": "script", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}, {"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "condition", "label": "Mais de 3 comments?", "operator": ">", "left_operand": "{{num_comments}}", "right_operand": "3"}, "html": "<div class=\"node-content\"><span>Mais de 3 comments?</span></div>", "name": "condition", "class": "condition", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}, "output_2": {"connections": [{"node": "7", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "log_node", "label": "Muitos Comentários", "level": "info", "message": "Post tem {{num_comments}} comentários!"}, "html": "<div class=\"node-content\"><span>Muitos Comentários</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "log_node", "label": "Poucos Comentários", "level": "warning", "message": "Post tem apenas {{num_comments}} comentários"}, "html": "<div class=\"node-content\"><span>Poucos Comentários</span></div>", "name": "log_node", "class": "log_node", "pos_x": 900, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}}}, "8": {"id": 8, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "6", "input": "output_1"}, {"node": "7", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 14:13:22.348311-03', '2026-03-23 14:13:22.348311-03');
INSERT INTO public.tb_pipelines VALUES (295, 'Teste 9 - Transforms Avançados', 'Filter→Limit→Aggregate(count)→Aggregate(max)', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"url": "https://jsonplaceholder.typicode.com/todos", "body": "", "type": "http_request", "label": "GET Todos", "method": "GET", "headers": "{}", "timeout": 15, "auth_type": "none", "output_variable": "all_todos"}, "html": "<div class=\"node-content\"><span>GET Todos</span></div>", "name": "http_request", "class": "http_request", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "transform", "label": "Filtrar Completos", "filter_field": "completed", "filter_value": "1", "input_variable": "all_todos", "transform_type": "filter", "filter_operator": "equals", "output_variable": "completed_todos"}, "html": "<div class=\"node-content\"><span>Filtrar Completos</span></div>", "name": "transform", "class": "transform", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "transform", "label": "Limitar 10", "limit_count": "10", "limit_offset": "0", "input_variable": "completed_todos", "transform_type": "limit", "output_variable": "limited_todos"}, "html": "<div class=\"node-content\"><span>Limitar 10</span></div>", "name": "transform", "class": "transform", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "transform", "label": "Agregar Count", "agg_field": "id", "agg_operation": "count", "input_variable": "limited_todos", "transform_type": "aggregate", "output_variable": "agg_count"}, "html": "<div class=\"node-content\"><span>Agregar Count</span></div>", "name": "transform", "class": "transform", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "transform", "label": "Agregar Max ID", "agg_field": "id", "agg_operation": "max", "input_variable": "limited_todos", "transform_type": "aggregate", "output_variable": "agg_max"}, "html": "<div class=\"node-content\"><span>Agregar Max ID</span></div>", "name": "transform", "class": "transform", "pos_x": 1100, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "log_node", "label": "Log Resultado", "level": "info", "message": "Filtrados: {{agg_count}}, Max ID: {{agg_max}}"}, "html": "<div class=\"node-content\"><span>Log Resultado</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "6", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}}}, "8": {"id": 8, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 14:13:23.072611-03', '2026-03-23 14:13:23.072611-03');
INSERT INTO public.tb_pipelines VALUES (296, 'Teste 10 - Pipeline CRON', 'Agendada para minuto 15 (CRON: 15 * * * *)', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger CRON", "trigger_type": "cron", "cron_expression": "15 * * * *"}, "html": "<div class=\"node-content\"><span>Trigger CRON</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Timestamp", "variable_name": "exec_time", "variable_value": "2026-03-23 18:13:23"}, "html": "<div class=\"node-content\"><span>Timestamp</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "log_node", "label": "Log CRON", "level": "info", "message": "Pipeline CRON executada em {{exec_time}}"}, "html": "<div class=\"node-content\"><span>Log CRON</span></div>", "name": "log_node", "class": "log_node", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', '15 * * * *', 'cron', '{}', 1, '["teste"]', 1, '2026-03-23 14:13:23.481665-03', '2026-03-23 14:13:23.481665-03');
