INSERT INTO public.tb_pipelines VALUES (311, 'Test Export JSON', '', 'nocode', false, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger"}, "html": "", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 200, "inputs": {}, "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}, "typenode": false}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Set_variable", "variable_name": "dados", "variable_value": "[{\"produto\":\"Notebook\",\"preco\":4500},{\"produto\":\"Mouse\",\"preco\":89.9}]"}, "html": "", "name": "set_variable", "class": "set_variable", "pos_x": 400, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}, "typenode": false}, "3": {"id": 3, "data": {"type": "file_export", "label": "File_export", "filename": "test_json_{datetime}", "json_pretty": "true", "export_format": "json", "input_variable": "{{dados}}", "export_directory": "storage/exports"}, "html": "", "name": "file_export", "class": "file_export", "pos_x": 700, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}, "typenode": false}, "4": {"id": 4, "data": {"type": "end", "label": "End"}, "html": "", "name": "end", "class": "end", "pos_x": 1000, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {}, "typenode": false}}}}}', '{"drawflow":{"Home":{"data":{"1":{"id":1,"name":"trigger","data":{"type":"trigger","label":"Trigger"},"class":"trigger","html":"","typenode":false,"inputs":{},"outputs":{"output_1":{"connections":[{"node":"2","output":"input_1"}]}},"pos_x":100,"pos_y":200},"2":{"id":2,"name":"set_variable","data":{"type":"set_variable","label":"Set_variable","variable_name":"dados","variable_value":"[{\"produto\":\"Notebook\",\"