INSERT INTO public.tb_pipelines VALUES (342, 'Teste 13 - Regex', 'Extração e teste com regex', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "SetTexto", "variable_name": "texto", "variable_value": "CPF: 123.456.789-00 e 987.654.321-11"}, "html": "<div class=\"node-content\"><span>SetTexto</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}, {"node": "4", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "regex", "label": "ExtrairCPF", "pattern": "/\\d{3}\\.\\d{3}\\.\\d{3}-\\d{2}/", "regex_mode": "match_all", "input_variable": "texto", "output_variable": "cpfs"}, "html": "<div class=\"node-content\"><span>ExtrairCPF</span></div>", "name": "regex", "class": "regex", "pos_x": 500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "regex", "label": "TestCPF", "pattern": "/\\d{3}\\.\\d{3}\\.\\d{3}-\\d{2}/", "regex_mode": "test", "input_variable": "texto", "output_variable": "tem_cpf"}, "html": "<div class=\"node-content\"><span>TestCPF</span></div>", "name": "regex", "class": "regex", "pos_x": 500, "pos_y": 250, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log", "log_message": "CPFs enc