INSERT INTO public.tb_pipelines VALUES (375, 'Teste 12 - Format Template', 'Formatação de texto com template', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}, {"node": "3", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "SetNome", "variable_name": "nome", "variable_value": "João"}, "html": "<div class=\"node-content\"><span>SetNome</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "set_variable", "label": "SetPedido", "variable_name": "pedido", "variable_value": "12345"}, "html": "<div class=\"node-content\"><span>SetPedido</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "format_template", "label": "Formatar", "template": "Olá {{nome}}, seu pedido #{{pedido}} foi confirmado.", "output_variable": "mensagem"}, "html": "<div class=\"node-content\"><span>Formatar</span></div>", "name": "format_template", "class": "format_template", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}, {"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "LogMsg", "log_message": "{{mensagem}}"}, "html": "<div class=\"no