INSERT INTO public.tb_pipelines VALUES (373, 'Teste 7 - Pipeline Grande (importado)', '11 nós: HTTP→Transform×2→Script→Condition→Loop→Log→End', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger Grande", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger Grande</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Def. API URL", "variable_name": "api_url", "variable_value": "https://jsonplaceholder.typicode.com/posts"}, "html": "<div class=\"node-content\"><span>Def. API URL</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"url": "{{api_url}}", "body": "", "type": "http_request", "label": "GET Posts", "method": "GET", "headers": "{}", "timeout": 20, "auth_type": "none", "output_variable": "posts"}, "html": "<div class=\"node-content\"><span>GET Posts</span></div>", "name": "http_request", "class": "http_request", "pos_x": 500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "transform", "label": "Limitar 5", "limit_count": "5", "limit_offset": "0", "input_variable": "posts", "transform_type": "limit", "output_variable": "top_posts"}, "html": "<div class=\"node-content\"><span>Limitar 5</span></div>", "name": "transform", "class": "transform", "pos_x": 700, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "transform", "label": "Contar", "agg_field": "id", "agg_operation": "count", "input_variable": "top_posts", "transform_type": "aggregate", "output_variable": "count_result"}, "html": "<div class=\"node-content\"><span>Contar</span></div>", "name": "transform", "class": "transform", "pos_x": 900, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "script", "label": "Extrair Contagem", "script_code": "is_array($count_result) ? ($count_result[\"value\"] ?? 0) : $count_result", "output_variable": "total_count", "script_language": "expression"}, "html": "<div class=\"node-content\"><span>Extrair Contagem</span></div>", "name": "script", "class": "script", "pos_x": 1100, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "condition", "label": "Posts >= 5?", "operator": ">=", "left_operand": "{{total_count}}", "right_operand": "5"}, "html": "<div class=\"node-content\"><span>Posts >= 5?</span></div>", "name": "condition", "class": "condition", "pos_x": 1300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "6", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "8", "output": "input_1"}]}, "output_2": {"connections": [{"node": "9", "output": "input_1"}]}}}, "8": {"id": 8, "data": {"type": "loop", "label": "Processar Posts", "input_variable": "top_posts", "max_iterations": 10, "output_variable": "processed", "iterator_variable": "post"}, "html": "<div class=\"node-content\"><span>Processar Posts</span></div>", "name": "loop", "class": "loop", "pos_x": 1500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "10", "output": "input_1"}]}}}, "9": {"id": 9, "data": {"type": "log_node", "label": "Log Poucos Posts", "level": "warning", "message": "Poucos posts: {{total_count}}"}, "html": "<div class=\"node-content\"><span>Log Poucos Posts</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1500, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "7", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "10", "output": "input_1"}]}}}, "10": {"id": 10, "data": {"type": "log_node", "label": "Log Final", "level": "info", "message": "Pipeline grande finalizada! {{total_count}} posts processados"}, "html": "<div class=\"node-content\"><span>Log Final</span></div>", "name": "log_node", "class": "log_node", "pos_x": 1700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "8", "input": "output_1"}, {"node": "9", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "11", "output": "input_1"}]}}}, "11": {"id": 11, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 1900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "10", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '[]', 1, '["teste"]', 1, '2026-03-23 14:46:02.666791-03', '2026-03-23 14:46:02.666791-03');
INSERT INTO public.tb_pipelines VALUES (362, 'Teste 1 - Pipeline Básica', 'Trigger manual, set variable, log, end', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger Manual", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger Manual</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Definir Nome", "variable_name": "nome_app", "variable_value": "DMC DataLoad"}, "html": "<div class=\"node-content\"><span>Definir Nome</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "log_node", "label": "Log Início", "level": "info", "message": "Pipeline iniciada: {{nome_app}}"}, "html": "<div class=\"node-content\"><span>Log Início</span></div>", "name": "log_node", "class": "log_node", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 14:45:57.849028-03', '2026-03-23 14:46:02.671122-03');
INSERT INTO public.tb_pipelines VALUES (374, 'Teste 11 - Switch/Case', 'Roteamento multi-branch', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "SetStatus", "variable_name": "status", "variable_value": "ativo"}, "html": "<div class=\"node-content\"><span>SetStatus</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "switch_case", "label": "Switch", "case_1": "ativo", "case_2": "inativo", "switch_variable": "status"}, "html": "<div class=\"node-content\"><span>Switch</span></div>", "name": "switch_case", "class": "switch_case", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}, "output_2": {"connections": [{"node": "5", "output": "input_1"}]}, "output_3": {"connections": [{"node": "6", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "log_node", "label": "Log Ativo", "log_message": "Status é ATIVO"}, "html": "<div class=\"node-content\"><span>Log Ativo</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log Inativo", "log_message": "Status é INATIVO"}, "html": "<div class=\"node-content\"><span>Log Inativo</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_2"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "log_node", "label": "Log Default", "log_message": "Status DESCONHECIDO"}, "html": "<div class=\"node-content\"><span>Log Default</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 350, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_3"}]}}, "outputs": {"output_1": {"connections": [{"node": "7", "output": "input_1"}]}}}, "7": {"id": 7, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}, {"node": "5", "input": "output_1"}, {"node": "6", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 14:46:02.680455-03', '2026-03-23 14:46:02.680455-03');
INSERT INTO public.tb_pipelines VALUES (377, 'Teste 14 - CSV Parse', 'Parse de CSV em array', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "set_variable", "label": "SetCSV", "variable_name": "csv_data", "variable_value": "nome,idade,cidade\nJoão,30,São Paulo\nMaria,25,Rio\nPedro,40,Curitiba"}, "html": "<div class=\"node-content\"><span>SetCSV</span></div>", "name": "set_variable", "class": "set_variable", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "csv_parse", "label": "ParseCSV", "delimiter": ",", "enclosure": "\"", "has_header": "true", "input_variable": "csv_data", "output_variable": "pessoas"}, "html": "<div class=\"node-content\"><span>ParseCSV</span></div>", "name": "csv_parse", "class": "csv_parse", "pos_x": 500, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "log_node", "label": "Log", "log_message": "Pessoas parseadas"}, "html": "<div class=\"node-content\"><span>Log</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 14:46:02.690327-03', '2026-03-23 14:46:02.690327-03');
INSERT INTO public.tb_pipelines VALUES (378, 'Teste 15 - Counter', 'Contador incremental', 'nocode', true, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger", "trigger_type": "manual"}, "html": "<div class=\"node-content\"><span>Trigger</span></div>", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 100, "inputs": [], "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}}, "2": {"id": 2, "data": {"type": "counter", "label": "SetInicial", "counter_name": "total", "counter_value": "10", "counter_action": "set", "output_variable": "total"}, "html": "<div class=\"node-content\"><span>SetInicial</span></div>", "name": "counter", "class": "counter", "pos_x": 300, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}}, "3": {"id": 3, "data": {"type": "counter", "label": "Incrementar1", "counter_name": "total", "counter_action": "increment", "output_variable": "total"}, "html": "<div class=\"node-content\"><span>Incrementar1</span></div>", "name": "counter", "class": "counter", "pos_x": 500, "pos_y": 50, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}}, "4": {"id": 4, "data": {"type": "counter", "label": "Incrementar2", "counter_name": "total", "counter_action": "increment", "output_variable": "total"}, "html": "<div class=\"node-content\"><span>Incrementar2</span></div>", "name": "counter", "class": "counter", "pos_x": 500, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "5", "output": "input_1"}]}}}, "5": {"id": 5, "data": {"type": "log_node", "label": "Log", "log_message": "Total: {{total}}"}, "html": "<div class=\"node-content\"><span>Log</span></div>", "name": "log_node", "class": "log_node", "pos_x": 700, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "4", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "6", "output": "input_1"}]}}}, "6": {"id": 6, "data": {"type": "end", "label": "Fim"}, "html": "<div class=\"node-content\"><span>Fim</span></div>", "name": "end", "class": "end", "pos_x": 900, "pos_y": 100, "inputs": {"input_1": {"connections": [{"node": "5", "input": "output_1"}]}}, "outputs": []}}}}}', '', '[]', NULL, 'manual', '{}', 1, '["teste"]', 1, '2026-03-23 14:46:02.692824-03', '2026-03-23 14:46:02.692824-03');
INSERT INTO public.tb_pipelines VALUES (379, 'Test Export CSV', '', 'nocode', false, '{"drawflow": {"Home": {"data": {"1": {"id": 1, "data": {"type": "trigger", "label": "Trigger"}, "html": "", "name": "trigger", "class": "trigger", "pos_x": 100, "pos_y": 200, "inputs": {}, "outputs": {"output_1": {"connections": [{"node": "2", "output": "input_1"}]}}, "typenode": false}, "2": {"id": 2, "data": {"type": "set_variable", "label": "Definir Dados", "variable_name": "dados", "variable_value": "[{\"nome\":\"Alice\",\"idade\":30,\"cidade\":\"S\\u00e3o Paulo\"},{\"nome\":\"Bob\",\"idade\":25,\"cidade\":\"Rio de Janeiro\"},{\"nome\":\"Carol\",\"idade\":35,\"cidade\":\"Belo Horizonte\"}]"}, "html": "", "name": "set_variable", "class": "set_variable", "pos_x": 400, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "1", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "3", "output": "input_1"}]}}, "typenode": false}, "3": {"id": 3, "data": {"type": "file_export", "label": "Export CSV", "filename": "test_csv_{datetime}", "export_format": "csv", "input_variable": "{{dados}}", "output_variable": "export_result", "export_directory": "storage/exports"}, "html": "", "name": "file_export", "class": "file_export", "pos_x": 700, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "2", "input": "output_1"}]}}, "outputs": {"output_1": {"connections": [{"node": "4", "output": "input_1"}]}}, "typenode": false}, "4": {"id": 4, "data": {"type": "end", "label": "End"}, "html": "", "name": "end", "class": "end", "pos_x": 1000, "pos_y": 200, "inputs": {"input_1": {"connections": [{"node": "3", "input": "output_1"}]}}, "outputs": {}, "typenode": false}}}}}', '{"drawflow":{"Home":{"data":{"1":{"id":1,"name":"trigger","data":{"type":"trigger","label":"Trigger"},"class":"trigger","html":"","typenode":false,"inputs":{},"outputs":{"output_1":{"connections":[{"node":"2","output":"input_1"}]}},"pos_x":100,"pos_y":200},"2":{"id":2,"name":"set_variable","dat